class LoginPage(BasePage):
    path = "/login"
    ready_locator = "[data-testid=login-form]"

    @property
    def username(self) -> Locator:        # a query, not a resolved element -- re-resolves on every action
        return self.testid("username")

    def login(self, username: str, password: str) -> "ProductsPage":
        """Happy path returns the destination page, so flows chain naturally."""
        self.username.fill(username)
        self.password.fill(password)
        self.submit.click()
        return ProductsPage(self.page).wait_until_ready()

    def login_expecting_failure(self, username: str, password: str) -> "LoginPage":
        """Negative path stays here. Separate method, separate return type."""
        self.username.fill(username)
        self.password.fill(password)
        self.submit.click()
        expect(self.error).not_to_be_empty()
        return self

class ProductCard:
    """Scoped to one card's root; every lookup is relative to it."""

    def __init__(self, root: Locator) -> None:
        self.root = root

    @property
    def name(self) -> str:
        return self.root.get_by_test_id("product-name").inner_text().strip()

    def add_to_cart(self) -> None:
        self.root.get_by_test_id("add-to-cart").click()


class BasePage:
    @property
    def is_mobile_layout(self) -> bool:
        viewport = self.page.viewport_size
        return bool(viewport and viewport["width"] <= 640)

    def open_nav(self):
        """Desktop shows the nav; mobile hides it behind a hamburger."""
        if self.is_mobile_layout:
            self.testid("menu-toggle").click()
            expect(self.testid("main-nav")).to_be_visible()
        return self


