class ApiError(AssertionError):
    """Inherits AssertionError for assertion-style semantics, not to control
    FAILED vs ERROR -- that split is decided by test phase, not exception type."""

    def __init__(self, response, expected):
        super().__init__(
            f"{response.request.method} {response.request.url} -> "
            f"{response.status_code} (expected {expected})\n{response.text[:2000]}"
        )


